typedef unsigned int size_t;

class color32 { public: unsigned int value; };
class FEMenuSystem;
class PauseMenuSystem;
class FEMenu;
class Font { public: enum HORIZJUST { HORIZJUST_LEFT, HORIZJUST_CENTER, HORIZJUST_RIGHT }; };

class stringx {
    void *data;
public:
    stringx(const stringx &);
    ~stringx();
};

class FEMenuEntry {
public:
    int entry_num;
    FEMenuEntry *next;
    FEMenuEntry *previous;
    FEMenu *menu;
protected:
    bool highlight;
    bool disabled;
    void *ent;
    color32 high_ent_color;
    color32 norm_ent_color;
    void *text;
private:
    float highlight_intensity;
    float highlight_timer;
    int disabled_alpha;
    color32 special_color;
    color32 special_color_high;
    bool has_special_color;
    bool no_flash;
    float special_scale;
    float special_scale_high;
    bool has_special_scale;
public:
    FEMenuEntry *up, *down, *left, *right;
    FEMenuEntry(stringx l, FEMenu *m, bool floating = false, Font *ft = 0) { cons(l, m, floating, ft); }
    virtual ~FEMenuEntry();
    virtual void Load();
    virtual void OnSelect();
    virtual void Highlight(bool = true, bool = true);
    virtual void Disable(bool = true);
    virtual bool GetDisable();
    virtual void Draw();
    virtual void Update(float);
    virtual void TurnOn(bool);
    virtual void SetSpecialColor(color32, color32);
    virtual void SetSpecialScale(float, float);
    virtual bool GetSpecialScale(float &, float &);
    virtual void SetNoFlash(bool);
    virtual float GetHighlightIntensity();
    virtual void SetPos(float, float);
    virtual void SetZ(int);
    virtual void SetText(stringx);
    virtual void SetLocation3D();
    virtual void SetHJustify(Font::HORIZJUST);
protected:
    virtual void cons(stringx, FEMenu *, bool = false, Font * = 0);
};

class FEMenu {
public:
    int center_x, center_y, num_entries, dy, half, menu_num;
    bool init;
    stringx font_filename;
    color32 color, color_high, color_high_alt;
    float scale, scale_high;
    int max_vis_entries, flags;
    FEMenuEntry *entries, *first_vis_entry, *last_vis_entry, *highlighted;
    FEMenuSystem *system;
    FEMenu *back;
    int back_num;
protected:
    FEMenu *submenus, *active, *parent;
    void *helpText;
    int helpFlags;
public:
    FEMenu *next_sub;
    FEMenu();
    virtual ~FEMenu();
    virtual void setBack(FEMenu *, int = 1);
    virtual void setHigh(FEMenuEntry *, bool = true);
    virtual void setVis(FEMenuEntry *);
    virtual void Add(FEMenuEntry *);
    virtual void Init();
    virtual void Load(bool);
    virtual void Load();
    virtual void Draw();
    virtual void DrawTop();
    virtual void UpdateInScene();
    virtual void Update(float);
    virtual void HighlightDefault();
    virtual void OnActivate();
    virtual void OnActivate(int);
    virtual void OnUnactivate(FEMenu *);
    virtual void OnSelect(int);
    virtual void OnStart(int);
    virtual void OnUp(int);
    virtual void OnDown(int);
    virtual void OnLeft(int);
    virtual void OnRight(int);
    virtual void OnCross(int);
    virtual void OnTriangle(int);
    virtual void OnSquare(int);
    virtual void OnCircle(int);
    virtual void OnL1(int);
    virtual void OnR1(int);
    virtual void OnL2(int);
    virtual void OnR2(int);
    virtual void OnAnyButtonPress(int, int);
    virtual void OnButtonRelease(int, int);
    virtual void SetAllScale(float);
    virtual void MakeActive(FEMenu *, bool = true);
    virtual void SetHelpText(int);
    virtual void Select(int);
protected:
    virtual void cons(FEMenuSystem *, int, int, color32, color32, color32, float = 1.0f, float = 1.2f, int = 8, int = 0);
private:
    char released_tail[0x20];
};

class LostControllerMenuClass : public FEMenu {
public:
    PauseMenuSystem *sys;
    LostControllerMenuClass(FEMenuSystem *, int, int, color32);
    virtual void Init();
    virtual void OnActivate();
    virtual void Update();
};

enum { FEMENU_WRAP = 0x002, GT_LOST_CONTROLLER = 1106 };
extern stringx ksGlobalTextArray[];
void *operator new(size_t, unsigned int, const char *, int);
#define NEW new(0, (const char *)0x004C3438, 0)

__asm__(".equ __6FEMenu, 0x00156280");
__asm__(".equ cons__6FEMenuP12FEMenuSystemiiG7color32N24ffii, 0x00156330");
__asm__(".equ Add__6FEMenuP11FEMenuEntry, 0x001566B8");
__asm__(".equ SetHelpText__6FEMenui, 0x00156E20");
__asm__(".equ cons__11FEMenuEntryG7stringxP6FEMenubP4Font, 0x001559B0");
__asm__(".equ __7stringxRC7stringx, 0x0034D4D0");
__asm__(".equ _$_7stringx, 0x0034D6E0");
